const FLOOR = 1440;
const FEET = 1404;
const R = fig(people.rishabh, 478, FEET, 640);
const N = fig(people.nandita, 604, FEET, 640);

type Toaster = { p: Person; o: Outfit; f: Fig; side: "l" | "r"; delay: number };
const toasters: Toaster[] = [
  { p: people.guestF1, o: wardrobe.guestF1.festive, f: fig(people.guestF1, 86, 2090, 760), side: "r", delay: 40 },
  { p: people.ashish, o: wardrobe.ashish.catalogue, f: fig(people.ashish, 236, 2160, 830), side: "r", delay: 52 },
  { p: people.hardik, o: wardrobe.hardik.catalogue, f: fig(people.hardik, 850, 2160, 830), side: "l", delay: 46 },
  { p: people.guestF2, o: wardrobe.guestF2.festive, f: fig(people.guestF2, 1000, 2090, 760), side: "l", delay: 58 },
];

/** Cold-pyro fountain: sparks shoot up from (x, y), slow, glitter and fade. */
const ColdPyro: React.FC<{ x: number; y: number; frame: number; on: number; seed: string; h?: number }> = ({ x, y, frame, on, seed, h = 420 }) => {
  const sparks = useMemo(
    () =>
      new Array(46).fill(0).map((_, i) => ({
        ph: random(`${seed}p${i}`) * 40,
        life: 26 + random(`${seed}l${i}`) * 18,
        vx: (random(`${seed}x${i}`) - 0.5) * 2.2,
        r: 1.4 + random(`${seed}r${i}`) * 2.2,
      })),
    [seed],
  );
  if (on <= 0) return null;
  return (
    <g opacity={on}>
      <ellipse cx={x} cy={y - 60} rx={50} ry={140} fill="#FFE6B0" opacity={0.08} />
      <path d={`M${x - 14} ${y} L${x + 14} ${y} L${x + 9} ${y - 18} L${x - 9} ${y - 18} Z`} fill={palette.goldDeep} />
      {sparks.map((s, i) => {
        const age = ((frame + s.ph) % s.life) / s.life;
        const rise = h * (1 - Math.pow(1 - age, 2));
        const sx = x + s.vx * age * 40 + Math.sin(age * 9 + i) * 3;
        const sy = y - 18 - rise;
        const a = (1 - age) * (0.55 + 0.45 * Math.sin(frame * 0.9 + i));
        return (
          <g key={i} opacity={Math.max(0, a)}>
            <path d={`M${sx} ${sy - s.r * 2.6} L${sx + s.r * 0.5} ${sy} L${sx} ${sy + s.r * 2.6} L${sx - s.r * 0.5} ${sy} Z`} fill={palette.goldPale} />
            <path d={`M${sx - s.r * 2.2} ${sy} L${sx} ${sy + s.r * 0.5} L${sx + s.r * 2.2} ${sy} L${sx} ${sy - s.r * 0.5} Z`} fill={palette.goldPale} />
          </g>
        );
      })}
    </g>
  );
};

/**
 * Reception — a glamorous night in a plum-and-champagne ballroom: cut-paper chandeliers descend
 * and sway, cold pyro glitters at the stage, and silhouetted guests raise their glasses to the couple.
 */
export const ReceptionScene: React.FC<SceneProps> = ({ inv, dur, solo }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  const k = solo ? 1.35 : 1; // solo: the same staging, allowed to breathe
  const cam = useCamera([
    { frame: 0, x: -34, scale: 1.0, y: 10 },
    { frame: dur - 4, x: 34, scale: solo ? 1.1 : 1.07, y: -16, ease: EASE.inOut },
  ]);

  const chand = [
    { x: 168, y: 330, s: 0.82, at: 6 },
    { x: 540, y: 140, s: 1.05, at: 16 },
    { x: 912, y: 330, s: 0.82, at: 26 },
  ].map((c, i) => {
    const d = prog(frame, c.at * k, 56 * k, EASE.out);
    const land = frame - (c.at + 56) * k;
    const settleSwing = land > 0 ? Math.sin(land / 14) * 1.6 * Math.exp(-land / 50) : 0;
    return { ...c, yy: c.y - (1 - d) * 760, swing: settleSwing + wave(frame, 150 + i * 20, i) * 0.8 };
  });
  const pyro = prog(frame, 56 * k, 20);

  // the couple, hand in hand, leaning in
  const clasp = toScene(R, 290, 560);
  const rPose: Partial<Pose> = { ...reachPose(R, null, clasp, -1, 1), lShoulder: 10, lElbow: -18, headTilt: 3 + wave(frame, 160) * 0.6 };
  const nPose: Partial<Pose> = { ...reachPose(N, clasp, null, -1, 1), rShoulder: -10, rElbow: 30, headTilt: -4 + wave(frame, 170, 1) * 0.6 };

  const ev = inv.events.reception;
  const date = formatEventDate(ev.date);
  const timeVenue = [ev.time, ev.venue].filter(Boolean).join(" · ");
  const lines = [date, timeVenue].filter(Boolean);
  const titleLines = lines.length ? lines : ["Details to follow"];
  const reveal = 52 + 8 * (titleLines.length - 1);
  const titleStart = Math.min(Math.round(92 * k), dur - 110 - reveal);

  return (
    <Stage background="#2A1C2E">
      <Camera state={cam}>
        {/* BACKGROUND — plum ballroom wall with glowing arched alcoves; the moon hung on its wire */}
        <ParallaxLayer depth={0.25} blurStrength={0}>
          <SVG>
            <defs>
              <linearGradient id="rcp-wall" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#1F1523" />
                <stop offset="0.5" stopColor="#3A2640" />
                <stop offset="1" stopColor="#2A1B2C" />
              </linearGradient>
              <linearGradient id="rcp-alcove" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#E9C98E" stopOpacity={0.05} />
                <stop offset="1" stopColor="#E9C98E" stopOpacity={0.32} />
              </linearGradient>
            </defs>
            <rect x={-200} y={-200} width={1480} height={2300} fill="url(#rcp-wall)" />
            {[-60, 170, 910, 1140].map((x) => (
              <g key={x}>
                <path d={archPath(x - 70, 140, 700, 560, 1440)} fill="url(#rcp-alcove)" />
                <path d={archPath(x - 70, 140, 700, 560, 1440)} fill="none" stroke={palette.gold} strokeWidth={1.4} opacity={0.6} />
                <path d={archPath(x - 70, 140, 700, 560, 1440)} fill="url(#jali)" opacity={0.25} />
              </g>
            ))}
            {[55, 285, 795, 1025].map((x) => (
              <g key={x}>
                <rect x={x - 16} y={420} width={32} height={1030} fill="#2A1C30" />
                <rect x={x - 16} y={420} width={5} height={1030} fill={palette.gold} opacity={0.35} />
                <rect x={x - 22} y={410} width={44} height={10} fill={palette.goldDeep} />
              </g>
            ))}
            <rect x={-200} y={404} width={1480} height={6} fill={palette.goldDeep} opacity={0.7} />
          </SVG>
        </ParallaxLayer>
        <ParallaxLayer depth={0.3} blurStrength={0}>
          <SVG>
            <SunOnWire t={0.25} moon />
          </SVG>
        </ParallaxLayer>

        {/* STAGE — champagne drape, floral arches, low stage */}
        <ParallaxLayer depth={0.7} blurStrength={0}>
          <SVG>
            <defs>
              <linearGradient id="rcp-drape" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#E8D6B4" />
                <stop offset="1" stopColor="#CDB58C" />
              </linearGradient>
            </defs>
            <path d={archPath(300, 480, 900, 640, 1410)} fill="url(#rcp-drape)" />
            {new Array(11).fill(0).map((_, i) => (
              <rect key={i} x={318 + i * 42} y={700} width={2} height={710} fill="#8C7350" opacity={0.18} />
            ))}
            <FloralArchFrame x0={284} x1={796} base={1410} top={610} seed="rcp-a1" r={22} tones={["ivory", "rose", "ivory", "ivory", "rose", "yellow"]} />
            <FloralArchFrame x0={110} x1={250} base={1410} top={820} seed="rcp-a2" r={17} tones={["ivory", "rose", "ivory"]} />
            <FloralArchFrame x0={830} x1={970} base={1410} top={820} seed="rcp-a3" r={17} tones={["rose", "ivory", "ivory"]} />
            <GarlandSwag from={[300, 760]} to={[780, 760]} sag={40} r={10} seed="rcp-sw" tones={["ivory", "rose", "ivory"]} />
            <rect x={-200} y={FLOOR - 30} width={1480} height={800} fill="#241826" />
            <path d={`M100 ${FLOOR - 36} L980 ${FLOOR - 36} L1010 ${FLOOR - 6} L70 ${FLOOR - 6} Z`} fill={palette.ivoryShade} />
            <rect x={70} y={FLOOR - 6} width={940} height={40} fill="#3A2640" />
            <rect x={70} y={FLOOR - 6} width={940} height={4} fill="url(#foil-h)" />
            <rect x={70} y={FLOOR + 30} width={940} height={3} fill={palette.gold} />
            {/* reflections of the chandeliers on the glossy floor */}
            {[168, 540, 912].map((x) => (
              <ellipse key={x} cx={x} cy={FLOOR + 190} rx={120} ry={18} fill="#FFE2A6" opacity={0.08} />
            ))}
            <FlowerHeap x={540} y={FLOOR - 30} w={820} r={14} seed="rcp-heap" tones={["ivory", "rose", "ivory", "yellow"]} />
          </SVG>
        </ParallaxLayer>

        <ParallaxLayer depth={0.75} blurStrength={0}>
          <Figure f={R} person={people.rishabh} outfit={wardrobe.rishabh.reception} pose={rPose} />
          <Figure f={N} person={people.nandita} outfit={wardrobe.nandita.reception} pose={nPose} />
          <SVG>
            <ColdPyro x={150} y={FLOOR - 30} frame={frame} on={pyro} seed="pyro-l" />
            <ColdPyro x={930} y={FLOOR - 30} frame={frame} on={pyro} seed="pyro-r" />
          </SVG>
          <GoldDust count={26} seed="rcp-dust" area={[240, 560, 600, 800]} start={Math.round(60 * k)} />
        </ParallaxLayer>

        {/* CHANDELIERS — descending on their threads */}
        <ParallaxLayer depth={0.9} blurStrength={0}>
          <SVG>
            {chand.map((c, i) => (
              <PaperChandelier key={i} x={c.x} y={c.yy} s={c.s} swing={c.swing} t={t + i} top={-300} />
            ))}
          </SVG>
        </ParallaxLayer>

        {/* FOREGROUND — guests raise their glasses, in silhouette */}
        <ParallaxLayer depth={1.3} blurStrength={0}>
          {toasters.map((m, i) => {
            const up = prog(frame, m.delay * k, 40 * k, EASE.inOut);
            const clink = Math.sin(prog(frame, (m.delay + 44) * k, 26 * k) * Math.PI) * 6;
            const [sx] = toScene(m.f, m.side === "r" ? 268 : 132, 238);
            const target: [number, number] = [sx + (m.side === "r" ? 1 : -1) * (18 + clink), m.f.feet - m.f.h * 0.86 - up * 150];
            const r = reach(m.f, m.side, target, m.side === "r" ? 1 : -1);
            const rest = m.side === "r" ? { rShoulder: -7, rElbow: 6 } : { lShoulder: 7, lElbow: -6 };
            const arm =
              m.side === "r"
                ? { rShoulder: rest.rShoulder! + (r.shoulder - rest.rShoulder!) * up, rElbow: rest.rElbow! + (r.elbow - rest.rElbow!) * up }
                : { lShoulder: rest.lShoulder! + (r.shoulder - rest.lShoulder!) * up, lElbow: rest.lElbow! + (r.elbow - rest.lElbow!) * up };
            const pose: Partial<Pose> = { ...arm, headTilt: m.side === "r" ? 3 : -3 };
            const hand =
              m.side === "r" ? handAt(m.f, "r", pose.rShoulder!, pose.rElbow!) : handAt(m.f, "l", pose.lShoulder!, pose.lElbow!);
            return (
              <React.Fragment key={i}>
                <Silhouette opacity={0.86} style={{ position: "absolute", inset: 0 }}>
                  <Figure f={m.f} person={m.p} outfit={m.o} pose={pose} />
                </Silhouette>
                <SVG>
                  <Flute x={hand[0]} y={hand[1] - 8} s={1.25} tilt={(m.side === "r" ? 10 : -10) * up} />
                </SVG>
              </React.Fragment>
            );
          })}
        </ParallaxLayer>
        <GoldDust count={18} seed="rcp-dust2" area={[0, 200, 1080, 1500]} start={Math.round(30 * k)} color={palette.goldLight} />
      </Camera>

      <SceneLighting
        warmth={0.2}
        keyX={50}
        keyY={40}
        spots={[
          { x: 50, y: 52, r: 44, color: "#FFE0A8", intensity: 0.26 },
          { x: 50, y: 12, r: 30, color: "#FFE6B8", intensity: 0.14 },
          { x: 14, y: 64, r: 20, color: "#FFE3A6", intensity: 0.2 * pyro },
          { x: 86, y: 64, r: 20, color: "#FFE3A6", intensity: 0.2 * pyro },
        ]}
        vignette={0.55}
      />

      <AbsoluteFill>
        <Gate from={titleStart}>
          <EventTitle start={titleStart} kicker="An Evening of Celebration" title={ev.title} lines={ev.date || ev.time || ev.venue ? [whenBi(ev.date, ev.time), bi(ev.venue)] : ["Details to follow"]} top={1612} titleSize={104} theme="light" />
        </Gate>
      </AbsoluteFill>

      <GoldFrame />
    </Stage>
  );
};
